def orphans(dburl, sitedir):
    """Remove all orphans in the site."""
    with open(dburl, 'r') as f:
        db = f.read()
    files = os.listdir(sitedir)
    for file in files:
        if file not in db:
            os.remove(os.path.join(sitedir, file))

