def execute(self, args):
        """Execute the hook followed by the playbook using the hook as tag."""
        hook = args.get("hook")
        playbook = args.get("playbook")
        tag = args.get("tag")
        if hook and playbook and tag:
            self.run_hook(hook)
            self.run_playbook(playbook, tag=tag)
        else:
            raise ValueError("Missing required arguments: hook, playbook, tag")

