def _distance_stats_sqr_fast_generic(x, y, dcov_function):
    """Compute the distance stats using the fast algorithm."""
    n = len(x)
    dcov_matrix = np.zeros((n, n))
    for i in range(n):
        for j in range(n):
            dcov_matrix[i, j] = dcov_function(x[i], y[j])
    dcov_vector = dcov_matrix.reshape(n * n)
    dcov_vector.sort()
    return dcov_vector[int(n * (n - 1) / 2)]

