def scale(stack_name: str,
          stack_version: Optional[str],
          new_scale: int,
          region: Optional[str],
          remote: Optional[str]):
    """Rescale a stack"""
    if not stack_name:
        raise ValueError("Stack name is required")
    if stack_version and not isinstance(stack_version, str):
        raise TypeError("Stack version must be a string")
    if not isinstance(new_scale, int):
        raise TypeError("New scale must be an integer")
    if region and not isinstance(region, str):
        raise TypeError("Region must be a string")
    if remote and not isinstance(remote, str):
        raise TypeError("Remote must be a string")
    print(f"Scaling stack {stack_name} to {new_scale} instances")
    if stack_version:
        print(f"Stack version: {stack_version}")
    if region:
        print(f"Region: {region}")
    if remote:
        print(f"Remote: {remote}")

