def validate(self):
        """ Simulataneously checks for loops and unreachable nodes
        """
        visited = set()
        def dfs(node):
            if node in visited:
                return False
            visited.add(node)
            for neighbor in node.neighbors:
                if not dfs(neighbor):
                    return False
            return True
        for node in self.nodes:
            if node not in visited:
                if not dfs(node):
                    return False
        return True

