hwc_code:
def _nest_vars_in_rec(var_items, rec_items, input_order, items_by_key, parallel):
    """Nest multiple variable inputs into a single record or list of batch records.

    Custom CWL implementations extract and merge these.
    """
    num_items = var_items
    var_items = list(var_items)[0]
    if rec_items:
        rec_items = list(rec_items)[0]
        if ((rec_items == 1 and var_items > 1) or parallel.startswith("batch")):
            num_items = set([rec_items])
            for var_key in (k for (k, t) in input_order.items() if t != "record"):
                var_key = tuple(var_key.split("__"))
                items_by_key[var_key] = [items_by_key[var_key]] * rec_items
        else:
            assert var_items == rec_items, (var_items, rec_items)
    return items_by_key, num_items

mgc_code:
def _nest_vars_in_rec(var_items, rec_items, input_order, items_by_key, parallel):
    """Nest multiple variable inputs into a single record or list of batch records.

    Custom CWL implementations extract and merge these.
    """
    if parallel:
        return [_nest_vars_in_rec(var_items, rec_items, input_order, items_by_key, False) for _ in rec_items]
    else:
        return {k: v for k, v in zip(input_order, [items_by_key[k] for k in input_order])}

solution:
ctype_args = [ None for _ in arguments]

for i, arg in enumerate(arguments):
    if not isinstance(arg, (numpy.ndarray, numpy.number)):
        raise TypeError("Argument is not numpy ndarray or numpy scalar %s" % type(arg))
    dtype_str = str(arg.dtype)
    data = arg.copy()
    if isinstance(arg, numpy.ndarray):
        if dtype_str in dtype_map.keys():
            # In numpy <= 1.15, ndarray.ctypes.data_as does not itself keep a reference
            # to its underlying array, so we need to store a reference to arg.copy()
            # in the Argument object manually to avoid it being deleted.
            # (This changed in numpy > 1.15.)
            data_ctypes = data.ctypes.data_as(C.POINTER(dtype_map[dtype_str]))
        else:
            raise TypeError("unknown dtype for ndarray")
    elif isinstance(arg, numpy.generic):
        data_ctypes = dtype_map[dtype_str](arg)
    ctype_args[i] = Argument(numpy=data, ctypes=data_ctypes)
return ctype_args

