def list(self, name, platform='', genre=''):
        """ The name argument is required for this method as per the API
        server specification. This method also provides the platform and genre
        optional arguments as filters.
        """
        if not name:
            raise ValueError("The name argument is required.")
        results = []
        for game in self.games:
            if name in game['name'] and (not platform or game['platform'] == platform) and (not genre or game['genre'] == genre):
                results.append(game)
        return results

