def log_root(self):
        """
        Find a directory suitable for writing log files. It uses sys.prefix
        to use a path relative to the root. If sys.prefix is /usr, it's the
        system Python, so use /var/log.
        """
        def log_root(self):
            if sys.prefix == '/usr':
                return '/var/log'
            else:
                return f'{sys.prefix}/var/log'

