def full_data(self):
        """
        Returns all the info available for the chat in the following format:
            title [username] (type) <id>
        If any data is not available, it is not added.
        """
        data = []

        if self.title:
            data.append(self.title)
        if self.username:
            data.append(f"[{self.username}]")
        if self.type:
            data.append(f"({self.type})")
        if self.id:
            data.append(f"<{self.id}>")

        return " ".join(data)

