mgc_code:
def _add_sv_coordinates(self, variant):
        """Add the neccesary sv coordinates for a variant

        Args:
            variant (puzzle.models.variant)
        """
        if variant.sv_type == "DEL":
            variant.end_chromosome = variant.chromosome
            variant.end_position = variant.position + len(variant.reference)
        elif variant.sv_type == "DUP":
            variant.end_chromosome = variant.chromosome
            variant.end_position = variant.position + len(variant.reference)
        elif variant.sv_type == "INS":
            variant.end_chromosome = variant.chromosome
            variant.end_position = variant.position
        elif variant.sv_type == "INV":
            variant.end_chromosome = variant.chromosome
            variant.end_position = variant.position + len(variant.reference)
        elif variant.sv_type == "BND":
            if variant.reference.startswith("["):
                variant.end_chromosome = variant.reference[1:].split(":")[0]
                variant.end_position = int(variant.reference[1:].split(":")[1].rstrip("]"))
            elif variant.reference.endswith("]"):
                variant.end_chromosome = variant.reference[:-1].split(":")[0]
                variant.end_position = int(variant.reference[:-1].split(":")[1].rstrip("["))
            else:
                raise ValueError("Invalid BND reference")
        else:
            raise ValueError("Invalid SV type")

