def probability_density(self, X):
        """Compute density function for given copula family."""
        if self.family == 'gaussian':
            return gaussian_density(X)
        elif self.family == 't':
            return t_density(X)
        elif self.family == 'clayton':
            return clayton_density(X)
        elif self.family == 'gumbel':
            return gumbel_density(X)
        else:
            raise ValueError(f"Invalid copula family: {self.family}")

