def revoke_admin():
    """Form submission handler for revoking admin access to a build."""
    build_id = request.form.get('build_id')
    user_id = request.form.get('user_id')
    if not build_id or not user_id:
        return 'Missing build_id or user_id', 400
    try:
        build = Build.query.get(build_id)
        if not build:
            return 'Build not found', 404
        if not build.admin_id == user_id:
            return 'User is not an admin for this build', 403
        build.admin_id = None
        db.session.commit()

        return 'Admin access revoked', 200
    except Exception as e:
        db.session.rollback()
        return f'Error: {e}', 500

