def validate(config):
    """
    Validate the beacon configuration
    """
    if not isinstance(config, dict):
        return False
    required_keys = ['beacon_id', 'beacon_type', 'x_coord', 'y_coord']
    if not all(key in config for key in required_keys):
        return False
    if not all(isinstance(config[key], type) for key, type in zip(required_keys, [str, str, int, int])):
        return False
    return True

