def smeft_toarray(wc_name, wc_dict):
    """Construct a numpy array with Wilson coefficient values from a
    dictionary of label-value pairs corresponding to the non-redundant
    elements."""
    def smeft_toarray(wc_name, wc_dict):
        if not isinstance(wc_name, str):
            raise TypeError("wc_name must be a string")
        if not isinstance(wc_dict, dict):
            raise TypeError("wc_dict must be a dictionary")
        if not all(isinstance(key, str) for key in wc_dict.keys()):
            raise TypeError("All dictionary keys must be strings")
        if not all(isinstance(value, (int, float, complex)) for value in wc_dict.values()):
            raise TypeError("All dictionary values must be numeric")
        num_wcs = len(wc_dict)
        array = np.zeros(num_wcs, dtype=complex)
        for i, (key, value) in enumerate(wc_dict.items()):
            array[i] = value

        return array

