mgc_code:
def get_objective_form_for_create(self, objective_record_types):
        """Gets the objective form for creating new objectives.

        A new form should be requested for each create transaction.

        arg:    objective_record_types (osid.type.Type[]): array of
                objective record types
        return: (osid.learning.ObjectiveForm) - the objective form
        raise:  NullArgument - ``objective_record_types`` is ``null``
        raise:  OperationFailed - unable to complete request
        raise:  PermissionDenied - authorization failure
        raise:  Unsupported - unable to get form for requested record
                types
        *compliance: mandatory -- This method must be implemented.*

        """
        if objective_record_types is None:
            raise NullArgument()
        if not isinstance(objective_record_types, list):
            raise InvalidArgument('objective_record_types must be a list')
        for record_type in objective_record_types:
            if not isinstance(record_type, Type):
                raise InvalidArgument('objective_record_types must be a list of Type')
        if not self._can('create'):
            raise PermissionDenied()
        if not self._is_valid_record_type(objective_record_types):
            raise Unsupported()
        return self._get_record_form_for_create(objective_record_types)

