            status = sample.sections[section].status
            if status == "PASS":
                status_cols.append("green")
            elif status == "WARN":
                status_cols.append("orange")
            elif status == "FAIL":
                status_cols.append("red")
            else:
                status_cols.append("gray")
        return status_cols

