def _pload(offset, size):
    """ Generic parameter loading.
    Emmits output code for setting IX at the right location.
    size = Number of bytes to load:
        1 => 8 bit value
        2 => 16 bit value / string
        4 => 32 bit value / f16 value
        5 => 40 bit value
    """
    if size == 1:
        return f"ld a, (ix+{offset})\n"
    elif size == 2:
        return f"ld bc, (ix+{offset})\n"
    elif size == 4:
        return f"ld de, (ix+{offset})\n"
    elif size == 5:
        return f"ld hl, (ix+{offset})\n"
    else:
        raise ValueError("Invalid size")

