def format(self):
        """
        Get format according to algorithm defined in RFC 5646 section 2.1.1.


        :return: formatted tag string.
        """
        parts = []
        if self.language:
            parts.append(self.language)
        if self.script:
            parts.append(self.script)
        if self.region:
            parts.append(self.region)
        if self.variants:
            parts.extend(self.variants)
        if self.extensions:
            parts.extend(self.extensions)
        return "-".join(parts)

