def queue(self, queue, message, params={}, uids=[]):
        """
        Queue a job in Rhumba
        """
        d = {
            'id': uuid.uuid1().get_hex(),
            'version': 1,
            'message': message,
            'params': params
        }

        if uids:
            for uid in uids:
                self._get_client().lpush('rhumba.dq.%s.%s' % (
                    uid, queue), json.dumps(d))
        else:
            self._get_client().lpush('rhumba.q.%s' % queue, json.dumps(d))

        return d['id']

