def queue(self, queue, message, params={}, uids=[]):
        """
        Queue a job in Rhumba
        """
        if not queue or not message:
            raise ValueError("Queue and message are required")
        if not isinstance(params, dict):
            raise TypeError("params must be a dict")
        if not isinstance(uids, list):
            raise TypeError("uids must be a list")
        return self.client.queue(queue, message, params, uids)

