def _num_vowel_to_acc(vowel, tone):
    """Convert a numbered vowel to an accented vowel."""
    vowel_map = {
        'a': ['a', 'á', 'a', 'a'],
        'e': ['e', 'é', 'e', 'e'],
        'i': ['i', 'í', 'i', 'i'],
        'o': ['o', 'ó', 'o', 'o'],
        'u': ['u', 'ú', 'u', 'u'],
    }
    return vowel_map[vowel][tone - 1]

