def edges(self, edges):
        """Specify edge list data and associated edge attribute values.

        :param edges: Edges and their attributes.
        :type point_size: Pandas dataframe, NetworkX graph, or IGraph graph.

        :returns: Plotter.
        :rtype: Plotter.

        **Example**
            ::

                import graphistry
                df = pandas.DataFrame({'src': [0,1,2], 'dst': [1,2,0]})
                graphistry
                    .bind(source='src', destination='dst')
                    .edges(df)
                    .plot()

        """
        if isinstance(edges, pd.DataFrame):
            self.edges_df = edges
        elif isinstance(edges, nx.Graph):
            self.edges_df = pd.DataFrame({
               'src': [u for u, v in edges.edges()],
                'dst': [v for u, v in edges.edges()],
            })
        elif isinstance(edges, ig.Graph):
            self.edges_df = pd.DataFrame({
               'src': edges.vs['name'],
                'dst': edges.vs['name'],
            })
        else:
            raise ValueError('Unsupported edges type')

