def print_exc_plus(stream=sys.stdout):
    """print normal traceback information with some local arg values"""
    tb = sys.exc_info()[2]
    while tb.tb_next:
        tb = tb.tb_next
    frame = tb.tb_frame
    for name, value in frame.f_locals.items():
        stream.write(f"{name}: {value}\n")
    traceback.print_exc(file=stream)

