def namedtuple_asdict(obj):
    """
    Serializing a nested namedtuple into a Python dict
    """
    if not isinstance(obj, namedtuple):
        return obj
    fields = obj._fields
    return {field: namedtuple_asdict(getattr(obj, field)) for field in fields}

