def check_has(priority=BaseCheck.HIGH, gname=None):
    """Decorator to wrap a function to check if a dataset has given attributes.
    :param function func: function to wrap"""
    def decorator(func):
        def wrapper(*args, **kwargs):
            if not hasattr(args[0], 'priority'):
                raise AttributeError("Missing attribute 'priority'")
            if not hasattr(args[0], 'gname'):
                raise AttributeError("Missing attribute 'gname'")
            return func(*args, **kwargs)
        return wrapper
    return decorator

