def get_newsitem_model(model_string):
    """
    Get the NewsItem model from a model string. Raises ValueError if the model
    string is invalid, or references a model that is not a NewsItem.
    """
    try:
        app_label, model_name = model_string.split('.')
    except ValueError:
        raise ValueError('Invalid model string')
    try:
        model = apps.get_model(app_label, model_name)
    except AppRegistryNotReady:
        raise ValueError('App registry not ready')
    except LookupError:
        raise ValueError('Model not found')
    if not issubclass(model, NewsItem):
        raise ValueError('Model is not a NewsItem')
    return model

