def count_statements(self, query, language='spo', type='triples',
                         flush=None):
        """
        Run a query in a format supported by the Fedora Resource Index
        (e.g., SPO or Sparql) and return the count of the results.

        :param query: query as a string
        :param language: query language to use; defaults to 'spo'
        :param flush: flush results to get recent changes; defaults to False
        :rtype: integer
        """
        if language =='spo':
            result = self.spo_query(query, flush=flush)
        elif language =='sparql':
            result = self.sparql_query(query, flush=flush)
        else:
            raise ValueError('Unsupported query language: {}'.format(language))

        if type == 'triples':
            return len(result)
        elif type =='statements':
            return len(set(result))
        else:
            raise ValueError('Unsupported result type: {}'.format(type))

