def _do_history(self, cmd, args):
        """\
        Display history.
            history             Display history.
            history clear       Clear history.
            history clearall    Clear history for all shells.
        """
        if len(args) == 0:
            for i, command in enumerate(self.history, 1):
                print(f"{i}: {command}")
        elif args[0] == "clear":
            self.history = []
        elif args[0] == "clearall":
            self.history = []
            for shell in self.shells.values():
                shell.history = []
        else:
