def _repair_row(self):
        """
        Searches for missing titles that can be inferred from the surrounding data and automatically
        repairs those titles.
        """
        for row_idx, row in enumerate(self.data):
            for col_idx, cell in enumerate(row):
                if cell is None:
                    surrounding_cells = []
                    for r in range(row_idx - 1, row_idx + 2):
                        for c in range(col_idx - 1, col_idx + 2):
                            if (0 <= r < len(self.data) and 0 <= c < len(self.data[0]) and
                                (r, c)!= (row_idx, col_idx)):
                                surrounding_cells.append(self.data[r][c])

                    if surrounding_cells:
                        inferred_title = max(surrounding_cells, key=lambda x: surrounding_cells.count(x))
                        self.data[row_idx][col_idx] = inferred_title

