def results_class_wise_average_metrics(self):
        """Class-wise averaged metrics

        Returns
        -------
        dict
            results in a dictionary format

        """
        results = {}
        for metric in self.metrics:
            results[metric] = {}
            for class_name in self.class_names:
                results[metric][class_name] = {}
                for phase in self.phases:
                    results[metric][class_name][phase] = {}
                    results[metric][class_name][phase]["f1"] = self.f1_class_wise_average[metric][class_name][phase]
                    results[metric][class_name][phase]["precision"] = self.precision_class_wise_average[metric][class_name][phase]
                    results[metric][class_name][phase]["recall"] = self.recall_class_wise_average[metric][class_name][phase]

        return results

