def prepare_project(project, project_dir, binaries, ips, urls):
    """
    Generates blacklists / whitelists
    """
    blacklist = []
    whitelist = []
    for binary in binaries:
        if binary in project['binaries']:
            whitelist.append(binary)
        else:
            blacklist.append(binary)
    for ip in ips:
        if ip in project['ips']:
            whitelist.append(ip)
        else:
            blacklist.append(ip)
    for url in urls:
        if url in project['urls']:
            whitelist.append(url)
        else:
            blacklist.append(url)
    return {'blacklist': blacklist, 'whitelist': whitelist}

