    else:
        try:
            idx = timeseries.index
            #Seasonal timeseries are stored in the year
            #1678 (the lowest year pandas allows for valid times).
            #Therefore if the timeseries is seasonal,
            #the request must be a seasonal request, not a
            #standard request

