                    ret_val = pandas_ts.loc[timestamp[0]].loc[col_name]
                else:
                    ret_val = pandas_ts.loc[timestamp][col_name].values.tolist()

            return ret_val

        except Exception as e:
            log.critical("Unable to retrive data. Check timestamps.")
            log.critical(e)

