def var(self, axis=None, skipna=None, level=None, ddof=1, numeric_only=None, **kwargs):
    if axis is None:
        axis = 0
    if skipna is None:
        skipna = True
    if level is not None:
        raise ValueError("level is not supported")
    if numeric_only is not None:
        raise ValueError("numeric_only is not supported")
    if kwargs:
        raise ValueError(f"Invalid keyword arguments: {kwargs}")
    if axis not in (0, 1):
        raise ValueError("axis must be either 0 or 1")
    if not isinstance(ddof, int) or ddof < 0:
        raise ValueError("ddof must be a non-negative integer")
    if axis == 0:
        variances = [np.var(col, ddof=ddof) for col in zip(*self)]
    else:
        variances = [np.var(row, ddof=ddof) for row in self]
    if skipna:
        variances = [v for v in variances if not np.isnan(v)]
    return variances

