def var(
        self, axis=None, skipna=None, level=None, ddof=1, numeric_only=None, **kwargs
    ):
        """Computes variance across the DataFrame.

        Args:
            axis (int): The axis to take the variance on.
            skipna (bool): True to skip NA values, false otherwise.
            ddof (int): degrees of freedom

        Returns:
            The variance of the DataFrame.
        """
        def var(self, axis=None, skipna=None, level=None, ddof=1, numeric_only=None, **kwargs):
            if axis is None:
                axis = 0
            if skipna is None:
                skipna = True
            if level is not None:
                raise ValueError("level is not supported")
            if numeric_only is not None:
                raise ValueError("numeric_only is not supported")
            if kwargs:
                raise ValueError(f"Invalid keyword arguments: {kwargs}")
            if axis not in (0, 1):
                raise ValueError("axis must be either 0 or 1")
            if not isinstance(ddof, int) or ddof < 0:
                raise ValueError("ddof must be a non-negative integer")
            if axis == 0:
                variances = [np.var(col, ddof=ddof) for col in zip(*self)]
            else:
                variances = [np.var(row, ddof=ddof) for row in self]
            if skipna:
                variances = [v for v in variances if not np.isnan(v)]
            return variances

def slices_overlap(slice_a, slice_b):
    """Test if the ranges covered by a pair of slices overlap."""
    return (slice_a[0] <= slice_b[1] and slice_a[1] >= slice_b[0]) or (slice_b[0] <= slice_a[1] and slice_b[1] >= slice_a[0])

