def jenkins_last_build_sha():
        """
        Returns the sha of the last completed jenkins build for this project.
        Expects JOB_URL in environment
        """
        job_url = os.environ.get('JOB_URL')
        if not job_url:
            raise ValueError('JOB_URL not set in environment')
        last_build_url = f'{job_url}lastBuild/api/json'
        with urllib.request.urlopen(last_build_url) as response:
            last_build_json = response.read().decode('utf-8')
        match = re.search(r'"sha":"([a-f0-9]+)"', last_build_json)
        if match:
            return match.group(1)
        else:
            raise ValueError('Could not find sha in lastBuild JSON')

