def copy(srcpath, dstpath, overwrite=True):
    """Copies the file or directory at `srcpath` to `dstpath`. Returns True if
    successful, False otherwise."""
    if os.path.exists(dstpath) and not overwrite:
        return False
    if os.path.isfile(srcpath):
        with open(srcpath, 'rb') as src_file, open(dstpath, 'wb') as dst_file:
            dst_file.write(src_file.read())
    else:
        shutil.copytree(srcpath, dstpath)

    return True

