def remove_fpaths(fpaths, verbose=VERBOSE, quiet=QUIET, strict=False,
                  print_caller=PRINT_CALLER, lbl='files'):
    """
    Removes multiple file paths
    """
    import utool as ut
    if print_caller:
        print(util_dbg.get_caller_name(range(1, 4)) + ' called remove_fpaths')
    n_total = len(fpaths)
    _verbose = (not quiet and n_total > 0) or VERYVERBOSE
    if _verbose:
        print('[util_path.remove_fpaths] try removing %d %s' % (n_total, lbl))
    n_removed = 0
    prog = ut.ProgIter(fpaths, label='removing files', enabled=verbose)
    _iter = iter(prog)
    # Try to be fast at first
    try:
        for fpath in _iter:
            os.remove(fpath)
            n_removed += 1
    except OSError as ex:
        # Buf if we fail put a try in the inner loop
        if VERYVERBOSE:
            print('WARNING: Could not remove fpath = %r' % (fpath,))
        if strict:
            util_dbg.printex(ex, 'Could not remove fpath = %r' % (fpath,),
                             iswarning=False)
            raise
        for fpath in _iter:
            try:
                os.remove(fpath)
                n_removed += 1
            except OSError as ex:
                if VERYVERBOSE:
                    print('WARNING: Could not remove fpath = %r' % (fpath,))
    if _verbose:
        print('[util_path.remove_fpaths] ... removed %d / %d %s' % (
            n_removed, n_total, lbl))
    return n_removed

mgc_code:
def remove_fpaths(fpaths, verbose=VERBOSE, quiet=QUIET, strict=False,
                  print_caller=PRINT_CALLER, lbl='files'):
    """
    Removes multiple file paths
    """
    if not isinstance(fpaths, list):
        raise TypeError('fpaths must be a list')
    if not all(isinstance(fpath, str) for fpath in fpaths):
        raise TypeError('all elements of fpaths must be strings')
    if not all(os.path.exists(fpath) for fpath in fpaths):
        if strict:
            raise FileNotFoundError('one or more file paths do not exist')
        else:
            fpaths = [fpath for fpath in fpaths if os.path.exists(fpath)]
    if print_caller:
        caller = get_caller()
        print(f'Called by {caller}')
    for fpath in fpaths:
        try:
            os.remove(fpath)
        except OSError as e:
            if not quiet:
                print(f'Error removing {fpath}: {e}')
    if verbose:
        print(f'Removed {len(fpaths)} {lbl}')

