mgc_code:
def associate_by_user_id(backend, details, response, user=None, *args, **kwargs):
    """
    Associate current auth with a user with the same Google user_id in the DB.
    """
    if user and user.is_authenticated:
        return user

    user_id = response.get('sub')
    if not user_id:
        return None

    from allauth.socialaccount.models import SocialAccount
    try:
        social_account = SocialAccount.objects.get(provider=backend.name, uid=user_id)
    except SocialAccount.DoesNotExist:
        return None

    return social_account.user

