def complete(self, uio, dropped=False):
        """Query for all missing information in the transaction"""
        if not uio.has_missing_info():
            return uio
        if not uio.has_missing_info("amount"):
            uio.amount = self.get_amount(uio.account, uio.currency)
        if not uio.has_missing_info("exchange_rate"):
            uio.exchange_rate = self.get_exchange_rate(uio.currency, uio.target_currency)
        if not uio.has_missing_info("commission"):
            uio.commission = self.get_commission(uio.account, uio.amount, uio.currency)
        if not uio.has_missing_info("target_amount"):
            uio.target_amount = uio.amount * uio.exchange_rate
        if not uio.has_missing_info("target_commission"):
            uio.target_commission = uio.commission * uio.exchange_rate
        if not uio.has_missing_info("total_target_amount"):
            uio.total_target_amount = uio.target_amount + uio.target_commission
        if not uio.has_missing_info("target_currency_balance"):
