def get_object_at(dictionary, path, attribute_name=None):
    """
    Get arbitrary object given a dictionary and path (list of keys)

    :param dictionary:
    :param path:
    :param attribute_name:
    :return:
    """
    o = dictionary
    try:
        for p in path:
            o = o[p]
        if attribute_name:
            return o[attribute_name]
        else:
            return o
    # failed to find attribute/key in dictionary
    except Exception:
        return {}

