def join(self, timeout=None):
        """Wait for this Task to end. If a timeout is given, after the time expires the function
        will return anyway."""
        if timeout is None:
            while self.is_alive():
                pass
        else:
            end_time = time.time() + timeout
            while self.is_alive():
                if time.time() >= end_time:
                    break

