def _visible_in_diff(merge_result, context_lines=3):
    """Collects the set of lines that should be visible in a diff with a certain number of context lines"""
    visible_lines = set()
    for line_number, line_type in merge_result:
        if line_type!= 'common':
            visible_lines.add(line_number)
        else:
            for i in range(line_number - context_lines, line_number + context_lines + 1):
                visible_lines.add(i)
    return visible_lines

