hwc_code:
def _getSnapshotIndex(self, t):
        """
        Return the index for the snapshot just before t
        """
        if t>self.tmax or t<self.tmin:
            raise ValueError("Requested time outside of baseline stored in binary file.")
        # Bisection method
        l = 0
        r = len(self)
        while True:
            bi = l+(r-l)//2
            if self.t[bi]>t:
                r = bi
            else:
                l = bi
            if r-1<=l:
                bi = l
                break
        return bi, self.t[bi]

mgc_code:
def _getSnapshotIndex(self, t):
        """
        Return the index for the snapshot just before t
        """
        left, right = 0, len(self.snapshots) - 1
        while left <= right:
            mid = (left + right) // 2
            if self.snapshots[mid].timestamp == t:
                return mid
            elif self.snapshots[mid].timestamp < t:
                left = mid + 1
            else:
                right = mid - 1
        return left - 1

