def add_semantic_hub_layout(cx, hub):
    """Attach a layout aspect to a CX network given a hub node."""
    layout_aspect = {
        "name": "layout",
        "nodes": [],
        "edges": []
    }
    for node in cx["nodes"]:
        if node["id"] == hub:
            node_layout = {
                "id": node["id"],
                "x": 0,
                "y": 0
            }
            layout_aspect["nodes"].append(node_layout)
    for edge in cx["edges"]:
        edge_layout = {
            "source": edge["source"],
            "target": edge["target"],
            "x": 0,
            "y": 0
        }
        layout_aspect["edges"].append(edge_layout)
    cx["aspects"].append(layout_aspect)

