def set_missing_value_policy(self, policy, target_attr_name=None):
        """
        Sets the behavior for one or all attributes to use when traversing the
        tree using a query vector and it encounters a branch that does not
        exist.
        """
        if target_attr_name is None:
            for attr_name in self.children.keys():
                self.children[attr_name].set_missing_value_policy(policy, target_attr_name)
        else:
            self.children[target_attr_name].set_missing_value_policy(policy, target_attr_name)

