hwc_code:
def merge(left, right):
    """
    deep merge dictionary on the left with the one
    on the right.

    Fill in left dictionary with right one where
    the value of the key from the right one in
    the left one is missing or None.
    """
    if isinstance(left, dict) and isinstance(right, dict):
        for key, value in right.items():
            if key not in left:
                left[key] = value
            elif left[key] is None:
                left[key] = value
            else:
                left[key] = merge(left[key], value)
    return left

mgc_code:
def merge(left, right):
    """
    deep merge dictionary on the left with the one
    on the right.

    Fill in left dictionary with right one where
    the value of the key from the right one in
    the left one is missing or None.
    """
    result = {}
    for key in left:
        if key in right:
            if isinstance(left[key], dict) and isinstance(right[key], dict):
                result[key] = merge(left[key], right[key])
            else:
                result[key] = right[key]
        else:
            result[key] = left[key]
    for key in right:
        if key not in left:
            result[key] = right[key]
    return result

