def get_balance(self, address, block="latest"):
        """
        https://github.com/ethereum/wiki/wiki/JSON-RPC#eth_getbalance
        """
        if not is_address(address):
            raise ValueError("Invalid address")
        if block not in ("latest", "earliest", "pending") and not isinstance(block, int):
            raise ValueError("Invalid block parameter")
        if isinstance(block, int):
            block = hex(block)
        response = self.send_request("eth_getBalance", [address, block])
        return int(response, 16)

