def section_bif_lengths(neurites, neurite_type=NeuriteType.all):
    """Bifurcation section lengths in a collection of neurites"""
    bif_lengths = defaultdict(list)
    for neurite in neurites:
        if neurite_type == NeuriteType.all or neurite.type == neurite_type:
            for section in neurite.iter_sections():
                if section.bifurcation_point:
                    bif_lengths[neurite.type].append(section.length)
    return bif_lengths

