def gzip_uncompress(data, truncated=False):
    decompressor = zlib.decompressobj(16 + 15 + 32)
    inflated_data = decompressor.decompress(data, zlib.MAX_WBITS | 16)
    if not truncated:
        inflated_data += decompressor.flush()
    return inflated_data

