def _escapify(qstring):
    """Escape the characters in a quoted string which need it.

    @param qstring: the string
    @type qstring: string
    @returns: the escaped string
    @rtype: string
    """
    if not qstring:
        return qstring
    escaped = ""
    for char in qstring:
        if char in '"\\':
            escaped += '\\'
        escaped += char
    return escaped

