def _is_exempt(self, environ):
        """
        Returns True if this request's URL starts with one of the
        excluded paths.
        """
        path = environ.get('PATH_INFO', '')
        for excluded_path in self.excluded_paths:
            if path.startswith(excluded_path):
                return True
        return False

