def __math(self, f, x):
        """operator function
        :param f: operator.add/sub/mul... used operator
        :param x: other object view should be add/sub... with (other View, number, numpy.ndarray, Field)
        :return: dictionary (same shape as field.d) with result of operation
        """
        if isinstance(x, View):
            result = {}
            for k in self.d:
                result[k] = f(self.d[k], x.d[k])
            return result
        elif isinstance(x, (int, float, np.ndarray)):
            result = {}
            for k in self.d:
                result[k] = f(self.d[k], x)
            return result
        elif isinstance(x, Field):
            result = {}
            for k in self.d:
                result[k] = f(self.d[k], x.d[k])
            return result
        else:
            raise TypeError("Unsupported type for operation")

