def prepare_notebook_context(request, notebook_context):
    """Fill in notebook context with default values."""
    if 'user_id' not in notebook_context:
        notebook_context['user_id'] = request.user.id
    if 'user_name' not in notebook_context:
        notebook_context['user_name'] = request.user.username
    if 'user_email' not in notebook_context:
        notebook_context['user_email'] = request.user.email
    if 'user_groups' not in notebook_context:
        notebook_context['user_groups'] = request.user.groups.all()
    if 'user_permissions' not in notebook_context:
        notebook_context['user_permissions'] = request.user.user_permissions.all()
    if'request_headers' not in notebook_context:
        notebook_context['request_headers'] = request.META
    return notebook_context

