def list_tickets(self, **kwargs):
        """List all tickets, optionally filtered by a view. Specify filters as
        keyword arguments, such as:

        filter_name = one of ['all_tickets', 'new_my_open', 'spam', 'deleted',
                               None]
            (defaults to 'all_tickets'; passing None uses the default)

        Multiple filters are AND'd together.
        """
        filter_name = kwargs.get('filter_name', 'all_tickets')
        if filter_name == 'all_tickets':
            return self.all_tickets
        elif filter_name == 'new_my_open':
            return self.new_my_open
        elif filter_name =='spam':
            return self.spam
        elif filter_name == 'deleted':
            return self.deleted
        else:
            return self.all_tickets

