        """This handles Ctrl+PageUp, Ctrl+PageDown, Ctrl+Tab, Ctrl+Shift+Tab"""
        incr = 0
        if evt.modifiers() == Qt.ControlModifier:
            n = self.tabWidget.count()
            if evt.key() in [Qt.Key_PageUp, Qt.Key_Backtab]:
                incr = -1
            elif evt.key() in [Qt.Key_PageDown, Qt.Key_Tab]:
                incr = 1
            if incr != 0:
                new_index = self._get_tab_index() + incr
                if new_index < 0:
                    new_index = n - 1
                elif new_index >= n:
                    new_index = 0
                self.tabWidget.setCurrentIndex(new_index)

mgc_code:
def keyPressEvent(self, evt):
        """This handles Ctrl+PageUp, Ctrl+PageDown, Ctrl+Tab, Ctrl+Shift+Tab"""
        if evt.key() == Qt.Key_PageUp and evt.modifiers() & Qt.ControlModifier:
            self.pageUp()
        elif evt.key() == Qt.Key_PageDown and evt.modifiers() & Qt.ControlModifier:
            self.pageDown()
        elif evt.key() == Qt.Key_Tab and evt.modifiers() & Qt.ControlModifier:
            if evt.modifiers() & Qt.ShiftModifier:
                self.prevTab()
            else:
                self.nextTab()

