mgc_code:
def process_filter_directive(filter_operation_info, location, context):
    """Return a Filter basic block that corresponds to the filter operation in the directive.

    Args:
        filter_operation_info: FilterOperationInfo object, containing the directive and field info
                               of the field where the filter is to be applied.
        location: Location where this filter is used.
        context: dict, various per-compilation data (e.g. declared tags, whether the current block
                 is optional, etc.). May be mutated in-place in this function!

    Returns:
        a Filter basic block that performs the requested filtering operation
    """
    filter_operation = filter_operation_info.filter_operation
    field_info = filter_operation_info.field_info
    if filter_operation == "equals":
        return Filter(
            location,
            context,
            field_info,
            lambda value: value == field_info.value,
        )
    elif filter_operation == "not_equals":
        return Filter(
            location,
            context,
            field_info,
            lambda value: value!= field_info.value,
        )
    elif filter_operation == "in":
        return Filter(
            location,
            context,
            field_info,
            lambda value: value in field_info.value,
        )
    elif filter_operation == "not_in":
        return Filter(
            location,
            context,
            field_info,
            lambda value: value not in field_info.value,
        )
    else:
        raise ValueError(f"Unknown filter operation: {filter_operation}")

