        @type node: xml.etree.Element
        """
        for child in node:
            if child.tag == "Event":
                event = child.text
            elif child.tag == "Command":
                command = child.text
            elif child.tag == "Parameter":
                parameter = child.text
            elif child.tag == "Condition":
                condition = child.text
            elif child.tag == "Action":
                action = child.text
        self.on_event(event, command, parameter, condition, action)

