def list_content_types(repo):
    """
    Return a list of content types in a repository.

    :param Repo repo:
        The git repository.
    :returns: list
    """
    content_types = set()
    for commit in repo.iter_commits():
        for diff in commit.diff():
            content_types.add(diff.change_type)
    return list(content_types)

