def quatInv(q):
    """Returns QBar such that Q*QBar = 1"""
    q_conj = (q[0], -q[1], -q[2], -q[3])
    norm_squared = q[0] ** 2 + q[1] ** 2 + q[2] ** 2 + q[3] ** 2
    return (q_conj[0] / norm_squared, q_conj[1] / norm_squared, q_conj[2] / norm_squared, q_conj[3] / norm_squared)

