def set_ys(self, word):
        """
        Identify Ys that are to be treated
        as consonants and make them uppercase.
        """
        for i in range(len(word)):
            if word[i] == 'y':
                if i == 0:
                    word = word[:i] + word[i].upper() + word[i+1:]
                elif word[i-1] not in self.vowels:
                    word = word[:i] + word[i].upper() + word[i+1:]

