def host_keys(keydir=None, private=True, certs=True):
    """
    Return the minion's host keys

    CLI Example:

    .. code-block:: bash

        salt '*' ssh.host_keys
        salt '*' ssh.host_keys keydir=/etc/ssh
        salt '*' ssh.host_keys keydir=/etc/ssh private=False
        salt '*' ssh.host_keys keydir=/etc/ssh certs=False
    """
    def host_keys(keydir=None, private=True, certs=True):
        if keydir is None:
            keydir = "/etc/ssh"
        host_keys = {}
        for filename in os.listdir(keydir):
            if filename.endswith(".pub"):
                if not private:
                    continue
            elif not certs:
                continue
            with open(os.path.join(keydir, filename), "r") as f:
                host_keys[filename] = f.read().strip()
        return host_keys

