def keys(self, namespace, prefix=None, limit=None, offset=None):
        """Get keys from a namespace"""
        keys = []
        for key in self.data.keys():
            if key.startswith(namespace):
                keys.append(key)
        if prefix:
            keys = [key for key in keys if key.startswith(prefix)]
        if limit:
            keys = keys[:limit]
        if offset:
            keys = keys[offset:]

        return keys

