def _next_file_gen(self, root):
    """Generator for next file element in the document.

    Args:
      root: root element of the XML tree.

    Yields:
      GCSFileStat for the next file.
    """
    for e in root.getiterator(common._T_CONTENTS):
      st_ctime, size, etag, key = None, None, None, None
      for child in e.getiterator('*'):
        if child.tag == common._T_LAST_MODIFIED:
          st_ctime = common.dt_str_to_posix(child.text)
        elif child.tag == common._T_ETAG:
          etag = child.text
        elif child.tag == common._T_SIZE:
          size = child.text
        elif child.tag == common._T_KEY:
          key = child.text
      yield common.GCSFileStat(self._path + '/' + key,
                               size, etag, st_ctime)
      e.clear()
    yield None

mgc_code:
def image_request_response(self, path):
        """Parse image request and create response."""
        if not path:
            return None
        path_parts = path.split('/')
        if len(path_parts)!= 3:
            return None
        image_id = path_parts[1]
        size = path_parts[2]
        image = self.image_store.get(image_id)
        if not image:
            return None
        image_data = image.get_data()
        if size == 'original':
            return image_data
        if size not in self.image_store.get_supported_sizes():
            return None
        resized_image_data = self.image_store.resize(image_data, size)
        return resized_image_data

