def ensure_backend(resource, backend, backends, opt, managed=True):
    """Ensure the backend for a resource is properly in context"""
    if backend not in backends:
        if managed:
            backends[backend] = resource.create_backend(backend)
        else:
            backends[backend] = resource.create_unmanaged_backend(backend)
    resource.set_backend(backends[backend])
    if opt:
        resource.optimize()

