def set_mode (filename, flags):
    """Set mode flags for given filename if not already set."""
    try:
        current_flags = os.stat(filename).st_mode
    except FileNotFoundError:
        current_flags = 0

    if current_flags!= flags:
        os.chmod(filename, flags)

