def cluster_nodes(self, tol=0.2):
        """
        Cluster nodes that are too close together using a tol.

        Args:
            tol (float): A distance tolerance. PBC is taken into account.
        """
        for node in self.nodes:
            if node.is_clustered:
                continue
            cluster = [node]
            for other_node in self.nodes:
                if other_node.is_clustered:
                    continue
                if node.distance(other_node) < tol:
                    cluster.append(other_node)
            for node in cluster:
                node.is_clustered = True
            self.clusters.append(cluster)

