def mw_wo_sw(mol, ndigits=2):
    """Molecular weight without salt and water
    :param ndigits: number of digits
    """
    mw_sw = 0
    for atom in mol:
        if atom!= 'Na' and atom!= 'Cl':
            mw_sw += atomic_mass[atom]
    return round(mw_sw, ndigits)

