def missing_or_other_newer(path, other_path, cwd=None):
    if cwd is not None:
        path = os.path.join(cwd, path)
        other_path = os.path.join(cwd, other_path)
    if not os.path.exists(path):
        return True
    path_stat = os.stat(path)
    other_path_stat = os.stat(other_path)
    return path_stat.st_mtime < other_path_stat.st_mtime

