def to_api_data(self, restrict_keys=None):
        """ Returns a dict to communicate with the server

        :param restrict_keys: a set of keys to restrict the returned data to
        :rtype: dict
        """
        if restrict_keys is None:
            return self.__dict__
        else:
            return {key: value for key, value in self.__dict__.items() if key in restrict_keys}

