def _logtrick_gen(bounds):
    """Generate warping functions and new bounds for the log trick."""
    def warp(x):
        return np.log(x)

    def unwarp(x):
        return np.exp(x)

    new_bounds = [np.log(b) for b in bounds]

    return warp, unwarp, new_bounds

