def all_dict_combinations_lbls(varied_dict, remove_singles=True, allow_lone_singles=False):
    comb_lbls = []
    for param_vals in itertools.product(*varied_dict.values()):
        param_dict = dict(zip(varied_dict.keys(), param_vals))
        if remove_singles and all(len(varied_dict[key]) == 1 for key in varied_dict):
            continue
        if not allow_lone_singles and any(len(varied_dict[key]) == 1 for key in varied_dict):
            continue
        comb_lbl = ', '.join('{}={}'.format(key, val) for key, val in param_dict.items())
        comb_lbls.append(comb_lbl)
    return comb_lbls

