def _execute(self, net):
        """Handle the combinational logic update rules for the given net.

        This function, along with edge_update, defined the semantics
        of the primitive ops. Function updates self.value accordingly.
        """
        if net.is_input:
            self.value = net.value
        elif net.is_and:
            self.value = self._execute_and(net)
        elif net.is_or:
            self.value = self._execute_or(net)
        elif net.is_xor:
            self.value = self._execute_xor(net)
        elif net.is_not:
            self.value = self._execute_not(net)
        else:
            raise ValueError(f"Unsupported net type: {net.type}")

