mgc_code:
def _import_protobuf_from_file(grpc_pyfile, method_name, service_name = None):
    """
    helper function which try to import method from the given _pb2_grpc.py file
    service_name should be provided only in case of name conflict
    return (False, None)  in case of failure
    return (True, (stub_class, request_class, response_class)) in case of success
    """
    try:
        module = __import__(grpc_pyfile.replace('.py', ''))
        if service_name:
            stub_class = getattr(module, f'{service_name}Stub')
            request_class = getattr(module, f'{service_name}Request')
            response_class = getattr(module, f'{service_name}Response')
        else:
            stub_class = getattr(module, f'{method_name}Stub')
            request_class = getattr(module, f'{method_name}Request')
            response_class = getattr(module, f'{method_name}Response')
        return (True, (stub_class, request_class, response_class))
    except Exception as e:
        return (False, None)

