def _get_pip_bin(bin_env):
    """
    Locate the pip binary, either from `bin_env` as a virtualenv, as the
    executable itself, or from searching conventional filesystem locations
    """
    if bin_env:
        return os.path.join(bin_env, 'pip')
    elif os.path.basename(sys.executable) == 'pip':
        return sys.executable
    else:
        for path in os.environ.get('PATH', '').split(os.pathsep):
            pip_path = os.path.join(path, 'pip')
            if os.path.exists(pip_path):
                return pip_path

    return None

def render_content(content, **kwargs):
    """check content for "active" urls, store results to django cache"""
    url_pattern = re.compile(r'https?://\S+')
    urls = url_pattern.findall(content)
    for url in urls:
        cache.set(url, is_active(url), **kwargs)

