def discover(service, timeout=5, retries=5):
    """
    Discovers services on a network using the SSDP Protocol.
    """
    group = ('239.255.255.250', 1900)
    message = '\r\n'.join([
        'M-SEARCH * HTTP/1.1',
        'HOST: {0}:{1}',
        'MAN: "ssdp:discover"',
        'ST: {st}', 'MX: 3', '', ''])
    socket.setdefaulttimeout(timeout)
    responses = {}

    for _ in range(retries):
        sock = socket.socket(
            socket.AF_INET, socket.SOCK_DGRAM,
            socket.IPPROTO_UDP
        )
        sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        sock.setsockopt(socket.IPPROTO_IP, socket.IP_MULTICAST_TTL, 2)
        data = message.format(*group, st=service)
        sock.sendto(data.encode('utf-8'), group)

        while True:
            try:
                response = SSDPResponse(sock.recv(1024))
                responses[response.location] = response
            except socket.timeout:
                break

        if responses:
            break

    return responses.values()

mgc_code:
def discover(service, timeout=5, retries=5):
    """
    Discovers services on a network using the SSDP Protocol.
    """
    ssdp_request = f"M-SEARCH * HTTP/1.1\r\nHOST: 172.16.17.32:1900\r\nMAN: ssdp:discover\r\nMX: {timeout}\r\nST: {service}\r\n\r\n"
    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    sock.settimeout(timeout)
    for _ in range(retries):
        sock.sendto(ssdp_request.encode(), ("172.16.17.32", 1900))
        try:
            while True:
                data, addr = sock.recvfrom(1024)
                yield data, addr
        except socket.timeout:
            pass

