def pixels_to_ndc(pos, size=None):
    """Convert from pixels to normalized device coordinates (in [-1, 1])."""
    if size is None:
        size = (1, 1)
    ndc_x = (pos[0] / size[0]) * 2 - 1
    ndc_y = (pos[1] / size[1]) * 2 - 1
    return (ndc_x, ndc_y)

