def uninstall(ctx, module_list):
    """ uninstall module """
    if not isinstance(ctx, dict):
        raise TypeError("ctx must be a dict")
    if not isinstance(module_list, list):
        raise TypeError("module_list must be a list")
    for module in module_list:
        if not isinstance(module, str):
            raise TypeError("module must be a str")
    for module in module_list:
        try:
            ctx["pip"].uninstall(module)
        except Exception as e:
            print(f"Error uninstalling {module}: {e}")
            return False
    return True

