def get_res_stats(self, nonzero=True):
    if nonzero:
        mask = self.observation_data['weight']!= 0
    else:
        mask = np.ones(len(self.observation_data), dtype=bool)
    groups = self.observation_data.groupby('group')
    stats = {}
    for group_name, group_data in groups:
        group_mask = mask & (self.observation_data['group'] == group_name)
        group_res = self.res[group_mask]
        group_obsval = self.observation_data.loc[group_mask, 'obsval']
        group_weight = self.observation_data.loc[group_mask, 'weight']
        stats[group_name] = {
           'min': np.min(group_res),
           'max': np.max(group_res),
           'mean': np.mean(group_res),
           'std': np.std(group_res),
            'rmse': np.sqrt(np.mean(group_res**2)),
            'norm_rmse': np.sqrt(np.mean(group_res**2)) / (np.max(group_obsval) - np.min(group_obsval)),
        }
    df = pd.DataFrame(stats).T
    return df

