def _norm_slices(self, fsls):
        """Convert slices to a normalized tuple of int/slice/farray."""
        if isinstance(fsls, (int, np.integer)):
            fsls = (fsls,)
        elif isinstance(fsls, slice):
            fsls = (fsls,)
