raw_output:
def verify_url_path(url_path, query_args, secret_key, salt_arg='_', max_expiry=None, digest=None):
    if not digest:
        digest = hashlib.sha256
    if salt_arg not in query_args:
        raise ValueError("Missing salt argument")
    salt = query_args[salt_arg]
    if max_expiry is not None:
        if 'expiry' not in query_args:
            raise ValueError("Missing expiry argument")
        expiry = int(query_args['expiry'])
        if expiry - int(time.time()) > max_expiry:
            raise ValueError("Expiry has expired")
    query_args_without_signature = {k: v for k, v in query_args.items() if k!='signature'}
    query_string = urllib.parse.urlencode(sorted(query_args_without_signature.items()))
    signature = digest(f"{url_path}?{query_string}{salt}{secret_key}".encode('utf-8')).hexdigest()
    if not hmac.compare_digest(signature, query_args['signature']):
        raise ValueError("Signature is invalid")

    return True

