raw_output:
def dot_product_attention(q, k, v, mask, dropout=0.0, dropout_broadcast_dims=None, extra_logit=None):
    depth_k = q.shape[-1]
    logits = np.matmul(q, k.transpose((-2, -1))) / math.sqrt(depth_k)
    if extra_logit is not None:
        logits += extra_logit
    if mask is not None:
        logits += mask
    weights = np.softmax(logits, axis=-1)
    if dropout > 0.0:
        weights = np.dropout(weights, rate=dropout, broadcast_dims=dropout_broadcast_dims)
    output = np.matmul(weights, v)

    return output

