def checkargs(self, lineno, command, args):
		"""
		Check if the arguments fit the requirements of the command.

		Raises ArgumentError_, if an argument does not fit.
		"""
def checkargs(self, lineno, command, args):
    if command == "set":
        if len(args)!= 2:
            raise ArgumentError(f"Line {lineno}: set requires two arguments")
    elif command == "get":
        if len(args)!= 1:
            raise ArgumentError(f"Line {lineno}: get requires one argument")
    elif command == "unset":
        if len(args)!= 1:
            raise ArgumentError(f"Line {lineno}: unset requires one argument")
    elif command == "numset":
        if len(args)!= 1:
            raise ArgumentError(f"Line {lineno}: numset requires one argument")
    elif command == "end":
        if len(args)!= 0:
            raise ArgumentError(f"Line {lineno}: end requires no arguments")
    else:
        raise ArgumentError(f"Line {lineno}: unknown command {command!r}")

