mgc_code:
def intersect(self, r):
        """Restrict self to common area with rectangle r."""
        x1 = max(self.x, r.x)
        y1 = max(self.y, r.y)
        x2 = min(self.x + self.width, r.x + r.width)
        y2 = min(self.y + self.height, r.y + r.height)
        if x1 < x2 and y1 < y2:
            return Rectangle(x1, y1, x2 - x1, y2 - y1)
        else:
            return None

