def infer_datetime_units(dates):
    if not dates:
        return None
    if len(dates) == 1:
        return "seconds since " + dates[0].isoformat()
    time_deltas = [dates[i] - dates[i-1] for i in range(1, len(dates))]
    unique_time_deltas = set(time_deltas)
    time_unit = None
    for unit in ["seconds", "minutes", "hours", "days"]:
        if all(timedelta(seconds=1) % delta == timedelta(0) for delta in unique_time_deltas):
            time_unit = unit
            break
    if time_unit is None:
        return None
    return f"{time_unit} since {dates[0].isoformat()}"

