def find_path(target, from_path=None, direction='both', depth_first=False):
    """
    Finds a file or subdirectory from the given
    path, defaulting to a breadth-first search.
    :param target:      str of file or subdirectory to be found
    :param from_path:   str of path from which to search (defaults to relative)
    :param direction:   str enum of up, down, both
    :param depth_first: bool of changes search to depth-first
    :return:            str of path to desired file or subdirectory
    """
    def find_path(target, from_path=None, direction='both', depth_first=False):
        if from_path is None:
            from_path = os.getcwd()
        if direction not in ['up', 'down', 'both']:
            raise ValueError("Invalid direction: must be 'up', 'down', or 'both'")
        if depth_first:
            search_order = ['down', 'up'] if direction == 'both' else [direction]
        else:
            search_order = ['up', 'down'] if direction == 'both' else [direction]
        for dir in search_order:
            for root, dirs, files in os.walk(from_path):
                if target in files or target in dirs:
                    return os.path.join(root, target)
                if dir == 'up':
                    from_path = os.path.dirname(from_path)
                elif dir == 'down':
                    for d in dirs:
                        path = find_path(target, os.path.join(root, d), direction=dir, depth_first=depth_first)
                        if path:
                            return path
        return None

