def tokenize(self):
    tokens = []
    pattern = re.compile(r"(?P<perl_tag><%.*?%>)|(?P<incl_tag><%.*?incl.*%>)", re.DOTALL)
    for match in re.finditer(pattern, self.text):
        if match.group("perl_tag"):
            tokens.append(("perl", match.start(), match.end()))
        elif match.group("incl_tag"):
            tokens.append(("incl", match.start(), match.end()))
    return tokens

