def eval_expr(expr_str, show_tokens=False, showast=False,
              showgrammar=False, compile_mode='exec'):
    """
    evaluate simple expression
    """
    if show_tokens:
        print("Tokens:")
        for token in tokenize.tokenize(expr_str.encode('utf-8')):
            print(token)
    if showast:
        print("AST:")
        print(ast.dump(ast.parse(expr_str)))
    if showgrammar:
        print("Grammar:")
        print(ast.dump_grammar())
    return eval(expr_str, {}, {})

