def _edit_linux_cmdline(cmdline, state, name, value=None):
    """
    Return a new Linux command line, with parameter `name` added,
    replaced, or removed.
    """
    kv = _parse_linux_cmdline(cmdline)
    if state == 'absent':
        try:
            del kv[name]
        except KeyError:
            pass
    elif state == 'present':
        kv[name] = value
    return _assemble_linux_cmdline(kv)

mgc_code:
def _edit_linux_cmdline(cmdline, state, name, value=None):
    """
    Return a new Linux command line, with parameter `name` added,
    replaced, or removed.
    """
    params = dict(pair.split('=') for pair in cmdline.split(' '))
    if state == 'add':
        params[name] = value
    elif state =='replace':
        params[name] = value
    elif state =='remove':
        params.pop(name, None)
    return''.join(f'{k}={v}' for k, v in params.items())

