def match_event_roll_lengths(event_roll_a, event_roll_b, length=None):
    m1, k1 = event_roll_a.shape
    m2, k2 = event_roll_b.shape
    if k1!= k2:
        raise ValueError("The number of columns in event_roll_a and event_roll_b must be the same.")
    if length is None:
        length = max(m1, m2)
    if m1 < length:
        event_roll_a = np.pad(event_roll_a, ((0, length - m1), (0, 0)), 'constant')
    if m2 < length:
        event_roll_b = np.pad(event_roll_b, ((0, length - m2), (0, 0)), 'constant')

    return event_roll_a, event_roll_b

