mgc_code:
def from_ast(
        pyast_node, node=None, node_cls=None, Node=Node,
        iter_fields=ast.iter_fields, AST=ast.AST):
    """Convert the ast tree to a tater tree.
    """
    if node is None:
        node = Node()
    if node_cls is None:
        node_cls = type(pyast_node)
    for field_name, field_value in iter_fields(pyast_node):
        if isinstance(field_value, AST):
            field_value = from_ast(field_value, node_cls=node_cls)
        elif isinstance(field_value, list):
            field_value = [from_ast(item, node_cls=node_cls) for item in field_value]
        setattr(node, field_name, field_value)
    return node

