mgc_code:
def deselect_by_index(self, index):
        """Deselect the option at the given index. This is done by examing the "index" attribute of an
           element, and not merely by counting.

           :Args:
            - index - The option at this index will be deselected

            throws NoSuchElementException If there is no option with specified index in SELECT
        """
        options = self.find_elements_by_tag_name("option")
        if len(options) == 0:
            raise NoSuchElementException("No options found in SELECT")

        try:
            index = int(index)
        except ValueError:
            raise ValueError("Index must be an integer")

        if index < 0 or index >= len(options):
            raise ValueError("Index out of range")

        for option in options:
            if option.get_attribute("index") == str(index):
                if option.get_attribute("selected") is not None:
                    option.click()
                break
        else:
            raise NoSuchElementException("No option with specified index found in SELECT")

