def patch(self, url, headers=None, body=None, kwargs=None):
        """Make a PATCH request.

        To make a PATCH request pass, ``url``

        :param url: ``str``
        :param headers: ``dict``
        :param body: ``object``
        :param kwargs: ``dict``
        """
        if not url:
            raise ValueError("Invalid URL")
        if headers and not isinstance(headers, dict):
            raise TypeError("Invalid headers")
        if body and not isinstance(body, object):
            raise TypeError("Invalid body")
        if kwargs and not isinstance(kwargs, dict):
            raise TypeError("Invalid kwargs")
        return self.request("PATCH", url, headers=headers, body=body, **kwargs)

