def heap_initializer(data, k, heaps, heap_args):
    n = data.shape[0]
    for i in range(n):
        for j in range(n):
            if i == j:
                continue
            dist_ij = dist(data[i], data[j], *dist_args)
            if heaps[i].size < k:
                heaps[i].push(j, dist_ij)
            else:
                if dist_ij < heaps[i].max_value():
                    heaps[i].replace_max(j, dist_ij)
            if heaps[j].size < k:
                heaps[j].push(i, dist_ij)
            else:
                if dist_ij < heaps[j].max_value():
                    heaps[j].replace_max(i, dist_ij)
    return heaps
return heap_initializer

