def sendPacket(self, completeBox):
        """
        Send a juice.Box to my peer.

        Note: transport.write is never called outside of this method.
        """
        assert not self.__locked, "You cannot send juice packets when a connection is locked"
        if self._startingTLSBuffer is not None:
            self._startingTLSBuffer.append(completeBox)
        else:
            if debug:
                log.msg("Juice send: %s" % pprint.pformat(dict(completeBox.iteritems())))

            self.transport.write(completeBox.serialize())

solution:
extractor = _fplib.Extractor(samplerate, channels, duration)

# Get first block.
try:
    next_block = next(pcmiter)
except StopIteration:
    raise ExtractionError()

# Get and process subsequent blocks.
while True:
    # Shift over blocks.
    cur_block = next_block
    try:
        next_block = next(pcmiter)
    except StopIteration:
        next_block = None
    done = next_block is None

    # Process the block.
    try:
        if extractor.process(cur_block, done):
            # Success!
            break
    except RuntimeError as exc:
        # Exception from fplib. Most likely the file is too short.
        raise ExtractionError(exc.args[0])

    # End of file but processor never became ready?
    if done:
        raise ExtractionError()

# Get resulting fingerprint data.
out = extractor.result()
if out is None:
    raise ExtractionError()

# Free extractor memory.
extractor.free()

return out

raw_output:
def extract(pcmiter, samplerate, channels, duration = -1):
    if not isinstance(pcmiter, bytes) or not isinstance(samplerate, int) or not isinstance(channels, int) or not isinstance(duration, int):
        raise TypeError("Invalid input type")
    if samplerate <= 0 or channels <= 0 or duration < -1:
        raise ValueError("Invalid input value")
    if duration == 0:
        return b""
    fingerprint_data = b""
    while True:
        pcm_data = next(pcmiter, None)
        if pcm_data is None:
            break
        fingerprint_data += pcm_data
        if duration > 0:
            duration -= len(pcm_data)
            if duration <= 0:
                break
    if len(fingerprint_data) == 0:
        raise ExtractionError("Fingerprinting failed")

    return fingerprint_data

