def extract(pcmiter, samplerate, channels, duration = -1):
    """Given a PCM data stream, extract fingerprint data from the
    audio. Returns a byte string of fingerprint data. Raises an
    ExtractionError if fingerprinting fails.
    """
    def extract(pcmiter, samplerate, channels, duration = -1):
        if not isinstance(pcmiter, bytes) or not isinstance(samplerate, int) or not isinstance(channels, int) or not isinstance(duration, int):
            raise TypeError("Invalid input type")
        if samplerate <= 0 or channels <= 0 or duration < -1:
            raise ValueError("Invalid input value")
        if duration == 0:
            return b""
        fingerprint_data = b""
        while True:
            pcm_data = next(pcmiter, None)
            if pcm_data is None:
                break
            fingerprint_data += pcm_data
            if duration > 0:
                duration -= len(pcm_data)
                if duration <= 0:
                    break
        if len(fingerprint_data) == 0:
            raise ExtractionError("Fingerprinting failed")

        return fingerprint_data

