mgc_code:
def Element(self, elem, **params):
        """Ensure that the input element is immutable by the transformation. Returns a single element."""
        if isinstance(elem, str):
            elem = self.Text(elem, **params)
        elif isinstance(elem, bytes):
            elem = self.Data(elem, **params)
        elif isinstance(elem, self.element_class):
            if elem.parent is not None:
                elem.detach()
        else:
            try:
                elem = self.element_class(elem, **params)
            except TypeError:
                raise ValueError("bad element type %r" % elem.__class__.__name__)
        return elem

