def generate_data_key(key_id, encryption_context=None, number_of_bytes=None,
                      key_spec=None, grant_tokens=None, region=None, key=None,
                      keyid=None, profile=None):
    """
    Generate a secure data key.

    CLI example::

        salt myminion boto_kms.generate_data_key 'alias/mykey' number_of_bytes=1024 key_spec=AES_128
    """
    if encryption_context is None:
        encryption_context = {}
    if number_of_bytes is None:
        number_of_bytes = 1024
    if key_spec is None:
        key_spec = 'AES_128'
    if grant_tokens is None:
        grant_tokens = []
    if region is None:
        region = 'us-east-1'
    if key is None:
        key = key_id
    if keyid is None:
        keyid = key_id
    if profile is None:
        profile = 'default'

    return {
        'KeyId': key_id,
        'Plaintext': b'plaintext',
        'CiphertextBlob': b'ciphertext'
    }

