def transform_coors(self, mtx_t, ref_coors=None):
    if ref_coors is None:
        ref_coors = self.coors
    if mtx_t.shape == (self.dim, self.dim):
        transformed_coors = np.dot(mtx_t, ref_coors)
    elif mtx_t.shape == (self.dim, self.dim + 1):
        transformed_coors = np.dot(mtx_t[:, :-1], ref_coors) + mtx_t[:, -1]
    else:
        raise ValueError("Invalid shape for the transformation matrix.")

    return transformed_coors

