mgc_code:
def directly_related(obj, count, collected_so_far, mods=[], only_from_same_site=True):
    """
    Returns objects related to ``obj`` up to ``count`` by searching
    ``Related`` instances for the ``obj``.
    """
    if count == 0:
        return collected_so_far
    for related in obj.related_set.filter(mods):
        if only_from_same_site and related.site!= obj.site:
            continue
        if related not in collected_so_far:
            collected_so_far.append(related)
            count -= 1
            if count == 0:
                return collected_so_far
    return collected_so_far

