    arguments set in self.urls. please check get_urls method in View.

    We could tie this to check_url_access() to check for permissions,
    including object-level.
    """
    if link in context.urls:
        url = context.urls[link]
        if args or kwargs:
            url += '?'
            if args:
                url += '&'.join(f'arg{i}={arg}' for i, arg in enumerate(args))
            if kwargs:
                url += '&' if args else ''
                url += '&'.join(f'{key}={value}' for key, value in kwargs.items())
        return url
    else:
        raise ValueError(f'Link "{link}" not found in context.urls')

