async def refresh_token(loader, client_configuration=None, interval=60):
    if client_configuration is None:
        client_configuration = kubernetes.client.Configuration()
    last_refresh_time = time.time()
    while True:
        if time.time() - last_refresh_time >= interval:
            token = await loader.load_and_set_csrf_token()
            client_configuration.api_key["authorization"] = f"Bearer {token}"
            last_refresh_time = time.time()
        await asyncio.sleep(interval)

