mgc_code:
def parse_locustfile(file_path):
    """ parse testcase file and return locustfile path.
        if file_path is a Python file, assume it is a locustfile
        if file_path is a YAML/JSON file, convert it to locustfile
    """
    if file_path.endswith('.py'):
        return file_path
    elif file_path.endswith('.json') or file_path.endswith('.yaml'):
        with open(file_path) as f:
            if file_path.endswith('.json'):
                data = json.load(f)
            else:
                data = yaml.load(f, Loader=yaml.FullLoader)
        locustfile_path = os.path.splitext(file_path)[0] + '.py'
        with open(locustfile_path, 'w') as f:
            f.write('class User(HttpUser):\n')
            for key, value in data.items():
                f.write(f'    {key} = {value}\n')
        return locustfile_path
    else:
        raise ValueError('Invalid file extension')

