def is_transition_matrix(T, tol=1e-12):
    if not isinstance(T, (np.ndarray, scipy.sparse.spmatrix)):
        return False
    if not np.all(T >= 0):
        return False
    if not np.allclose(np.sum(T, axis=1), 1, atol=tol):
        return False

    return True

