def documentation(self, add_to=None, version=None, prefix="", base_url="", url=""):
        """Returns the documentation specific to an HTTP interface"""
        if add_to is None:
            add_to = {}
        if version is None:
            version = self.version
        if prefix is None:
            prefix = self.prefix
        if base_url is None:
            base_url = self.base_url
        if url is None:
            url = self.url
        add_to["version"] = version
        add_to["prefix"] = prefix
        add_to["base_url"] = base_url
        add_to["url"] = url

        return add_to

