import os
from os import path

bottom = path.realpath(bottom)

# get files in current dir
try:
    names = os.listdir(bottom)
except Exception as e:
    raise e

dirs, nondirs = [], []
for name in names:
    if path.isdir(path.join(bottom, name)):
        dirs.append(name)
    else:
        nondirs.append(name)

yield bottom, dirs, nondirs

new_path = path.realpath(path.join(bottom, '..'))

# see if we are at the top
if new_path == bottom:
    return

for x in walk_up(new_path):
    yield x

hwc_code:
def walk_up(bottom):
    """  mimic os.walk, but walk 'up' instead of down the directory tree
    :param bottom:
    :return:
    """
    import os
    from os import path

    bottom = path.realpath(bottom)

    # get files in current dir
    try:
        names = os.listdir(bottom)
    except Exception as e:
        raise e

    dirs, nondirs = [], []
    for name in names:
        if path.isdir(path.join(bottom, name)):
            dirs.append(name)
        else:
            nondirs.append(name)

    yield bottom, dirs, nondirs

    new_path = path.realpath(path.join(bottom, '..'))

    # see if we are at the top
    if new_path == bottom:
        return

    for x in walk_up(new_path):
        yield x

