def _api_key_patch_replace(conn, apiKey, path, value):
    """
    the replace patch operation on an ApiKey resource
    """
    if path == "/metadata":
        if not isinstance(value, dict):
            raise ValueError("Invalid value for metadata: must be a dict")
        apiKey.metadata = value
    elif path == "/spec/displayName":
        if not isinstance(value, str):
            raise ValueError("Invalid value for displayName: must be a string")
        apiKey.spec.displayName = value
    elif path == "/spec/expirationTime":
        if not isinstance(value, str):
            raise ValueError("Invalid value for expirationTime: must be a string")
        apiKey.spec.expirationTime = value
    elif path == "/spec/keyType":
        if not isinstance(value, str):
            raise ValueError("Invalid value for keyType: must be a string")
        apiKey.spec.keyType = value
    elif path == "/spec/state":
        if not isinstance(value, str):
            raise ValueError("Invalid value for state: must be a string")
        apiKey.spec.state = value
    else:
        raise ValueError(f"Invalid path: {path}")
    conn.patch_api_key(apiKey)

